import fs from 'node:fs';
import path from 'node:path';

// Links from OJ problems back to the training-path site (generated by
// 培訓路線網站_L0-L3/教師版/tools/build_oj_backlinks.py → src/content/flowershow-links.json).
export const FLOWERSHOW_URL = 'https://algorithm-cdsj5it2008.flowershow.me/';
export type LessonLink = { en: string; zh: string; url: string };

let cache: Record<string, LessonLink[]> | null = null;
export function getLessonLinks(slug: string): LessonLink[] {
  if (!cache) {
    try {
      cache = JSON.parse(fs.readFileSync(path.join(process.cwd(), 'src', 'content', 'flowershow-links.json'), 'utf8'));
    } catch {
      cache = {};
    }
  }
  return cache?.[slug] ?? [];
}
